def toggle_case_by_index(s):
    chars = []
    for i, ch in enumerate(s):
        chars.append(ch.lower() if i % 2 else ch.upper())
    return ''.join(chars)

def to_kebab_case(s):
    words = []
    current = ''
    for ch in s:
        if ch == '_' or ch == ' ':
            if current:
                words.append(current)
                current = ''
        else:
            current += ch
    if current:
        words.append(current)
    return '-'.join(w.lower() for w in words)

