def is_valid_12h_time(s):
    if len(s) != 8:
        return False
    hh, colon, mm, space, marker = s[0:2], s[2], s[3:5], s[5], s[6:8]
    if colon != ':' or space != ' ':
        return False
    if not hh.isdigit() or not mm.isdigit():
        return False
    if marker not in ('AM', 'PM'):
        return False
    h, m = int(hh), int(mm)
    return 1 <= h <= 12 and 0 <= m <= 59

