def find_repeated_substrings_of_length(s, k):
    if k <= 0 or k > len(s):
        return []
    counts = {}
    for i in range(len(s) - k + 1):
        sub = s[i:i + k]
        counts[sub] = counts.get(sub, 0) + 1
    added = set()
    result = []
    for i in range(len(s) - k + 1):
        sub = s[i:i + k]
        if counts[sub] > 1 and sub not in added:
            result.append(sub)
            added.add(sub)
    return result

