def nth_prime(n):
    def is_prime(x):
        if x < 2:
            return False
        i = 2
        while i * i <= x:
            if x % i == 0:
                return False
            i += 1
        return True
    candidate = 1
    found = 0
    while found < n:
        candidate += 1
        if is_prime(candidate):
            found += 1
    return candidate

