import itertools
def modified_competition_rank(nums):
    s = sorted(nums)
    rank_map = {}
    idx = 0
    for value, group in itertools.groupby(s):
        idx += len(list(group))
        rank_map[value] = idx
    return [rank_map[x] for x in nums]

